<?php
declare(strict_types=1);
namespace Moves\Services;
use InvalidArgumentException;use MovesCode\Storage\Send;use RuntimeException;
/** Armazenamento privado reutilizável para comprovantes e anexos empresariais. */
final class OrganizationFiles
{
 private const MIMES=['image/jpeg','image/png','image/webp','application/pdf','text/plain'];private const EXT=['jpg','jpeg','png','webp','pdf','txt'];private const MAX=10485760;
 public static function validate(array $files):void{if(count($files)>5)throw new InvalidArgumentException('Envie no máximo 5 arquivos.');foreach($files as$file){if(($file['error']??1)!==UPLOAD_ERR_OK||(int)($file['size']??0)<1||(int)$file['size']>self::MAX)throw new InvalidArgumentException('Arquivo inválido ou acima de 10 MB.');$mime=(string)(new \finfo(FILEINFO_MIME_TYPE))->file((string)$file['tmp_name']);$ext=strtolower(pathinfo((string)$file['name'],PATHINFO_EXTENSION));if(!in_array($mime,self::MIMES,true)||!in_array($ext,self::EXT,true))throw new InvalidArgumentException('Formato não permitido. Use imagem, PDF ou texto.');}}
 public static function store(int $organizationId,string $area,array $file):array{self::validate([$file]);$root=self::root($organizationId,$area);$original=mb_substr(basename((string)$file['name']),0,190);try{$mime=(string)(new \finfo(FILEINFO_MIME_TYPE))->file((string)$file['tmp_name']);$path=(new Send($root,'files',self::MIMES,self::EXT))->upload($file,pathinfo($original,PATHINFO_FILENAME));}catch(RuntimeException){throw new InvalidArgumentException('Não foi possível armazenar o arquivo.');}return['path'=>substr($path,strlen($root)+1),'name'=>$original,'mime'=>$mime,'size'=>(int)filesize($path)];}
 public static function stream(int $organizationId,string $area,array $row):void{$root=realpath(self::root($organizationId,$area));$path=realpath(self::root($organizationId,$area).'/'.$row['stored_path']);if($root===false||$path===false||!str_starts_with($path,$root.'/')||!is_file($path)){AppError::render(404);return;}$name=str_replace(['"','\\',"\r","\n"],'',(string)$row['original_name']);header('Content-Type: '.(in_array($row['mime_type'],self::MIMES,true)?$row['mime_type']:'application/octet-stream'));header('Content-Disposition: attachment; filename="'.$name.'"');header('X-Content-Type-Options: nosniff');header('Content-Security-Policy: sandbox');header('Cache-Control: private, no-store');header('Content-Length: '.filesize($path));readfile($path);}
 public static function remove(int $organizationId,string $area,string $stored):void{$root=realpath(self::root($organizationId,$area));$path=realpath(self::root($organizationId,$area).'/'.$stored);if($root!==false&&$path!==false&&str_starts_with($path,$root.'/')&&is_file($path))unlink($path);}
 private static function root(int $organizationId,string $area):string{if(!preg_match('/^[a-z-]+$/',$area))throw new RuntimeException('Área de arquivos inválida.');$root=BASE_PATH.'/storage/organizations/'.$organizationId.'/'.$area;if(!is_dir($root)&&!mkdir($root,0750,true)&&!is_dir($root))throw new RuntimeException('Armazenamento empresarial indisponível.');return$root;}
}
